#define CL_TARGET_OPENCL_VERSION 120
#include <CL/cl.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#define CHECK(c) do{cl_int err=(c);if(err){fprintf(stderr,"%s: %d\n",#c,err);return 2;}}while(0)
int main(int argc,char**argv){cl_platform_id p;cl_device_id d;cl_uint count;cl_int e;CHECK(clGetPlatformIDs(1,&p,&count));CHECK(clGetDeviceIDs(p,CL_DEVICE_TYPE_GPU,1,&d,&count));cl_context c=clCreateContext(NULL,1,&d,NULL,NULL,&e);CHECK(e);cl_command_queue q=clCreateCommandQueue(c,d,0,&e);CHECK(e);
const char*s="__kernel void copy(uint d0,uint s0,uint t0,uint d1,uint s1,uint t1,uint d2,uint s2,uint t2,__global const float*x,uint xo,__global float*y,uint yo){uint g=get_global_id(0);uint i0=g/6720,i1=(g/5)%1344,i2=g%5;y[yo+g]=x[xo+i0*s0+i1*s1+i2*s2];} __kernel void verify(__global const uint*x,__global const uint*y,__global uint*f){if(get_global_id(0))return;f[0]=0;for(uint i=0;i<13440;i++){uint b=i/6720,r=(i/5)%1344,c=i%5;uint expected=x[86016+b*92736+r+c*1344],actual=y[i];if(actual!=expected){f[0]=i+1;f[1]=actual;f[2]=expected;return;}}}";
cl_program pr=clCreateProgramWithSource(c,1,&s,NULL,&e);CHECK(e);CHECK(clBuildProgram(pr,1,&d,"",NULL,NULL));cl_kernel k=clCreateKernel(pr,"copy",&e);CHECK(e);uint32_t n=2*69*1344,m=2*5*1344;uint32_t *x=malloc(n*4),*h=malloc(n*4);for(uint32_t i=0;i<n;i++)x[i]=0x3f800000u+i;size_t global[3]={13440,1,1},local[3]={64,1,1};int explicit=argc>1;if(argc>2)local[0]=strtoul(argv[2],NULL,10);
for(unsigned trial=0;trial<250;trial++){cl_mem a=clCreateBuffer(c,CL_MEM_READ_WRITE|CL_MEM_COPY_HOST_PTR,n*4,x,&e);CHECK(e);cl_mem b=clCreateBuffer(c,CL_MEM_READ_WRITE,m*4,NULL,&e);CHECK(e);CHECK(clEnqueueReadBuffer(q,a,CL_TRUE,0,n*4,h,0,NULL,NULL));for(uint32_t i=0;i<n;i++)if(h[i]!=x[i]){printf("INPUTFAIL %u %u %u\n",trial,i,h[i]);return 1;}
cl_mem flag=clCreateBuffer(c,CL_MEM_READ_WRITE,12,NULL,&e);CHECK(e);uint32_t params[]={2,69*1344,5*1344,1344,1,5,5,1344,1};for(int i=0;i<9;i++)CHECK(clSetKernelArg(k,i,4,&params[i]));uint32_t zero=0,xoffset=86016;CHECK(clSetKernelArg(k,9,sizeof(a),&a));CHECK(clSetKernelArg(k,10,4,&xoffset));CHECK(clSetKernelArg(k,11,sizeof(b),&b));CHECK(clSetKernelArg(k,12,4,&zero));CHECK(clEnqueueNDRangeKernel(q,k,1,NULL,global,explicit?local:NULL,0,NULL,NULL));CHECK(clFinish(q));cl_kernel vk=clCreateKernel(pr,"verify",&e);CHECK(e);CHECK(clSetKernelArg(vk,0,sizeof(a),&a));CHECK(clSetKernelArg(vk,1,sizeof(b),&b));CHECK(clSetKernelArg(vk,2,sizeof(flag),&flag));size_t one=1;CHECK(clEnqueueNDRangeKernel(q,vk,1,NULL,&one,&one,0,NULL,NULL));CHECK(clFinish(q));uint32_t flags[3]={0};CHECK(clEnqueueReadBuffer(q,flag,CL_TRUE,0,sizeof(flags),flags,0,NULL,NULL));if(flags[0])printf("GPUVERIFY trial%u index%u actual%u expected%u\n",trial,flags[0]-1,flags[1],flags[2]);clReleaseKernel(vk);clReleaseMemObject(flag);CHECK(clEnqueueReadBuffer(q,b,CL_TRUE,0,m*4,h,0,NULL,NULL));unsigned bad=0;for(uint32_t i=0;i<m;i++){uint32_t batch=i/(5*1344),row=i/5%1344,ch=i%5,expected=86016+batch*69*1344+row+ch*1344;expected=x[expected];if(h[i]!=expected){if(bad<8)printf("BAD %u index%u expected%u actual%u\n",trial,i,expected,h[i]);bad++;}}printf("trial%u bad%u\n",trial,bad);fflush(stdout);if(bad)return 1;clReleaseMemObject(a);clReleaseMemObject(b);}
puts("PASS250");return 0;}
